public static GUPPriceComponentCodeSetup findByName(GUPPriceComponentCodeName _priceComponentCodeName, boolean _update = false)
{
    GUPPriceComponentCodeSetup         priceMarginCompSetup;

    if(_update)
    {
        priceMarginCompSetup.selectForUpdate(_update);
    }

    select firstonly priceMarginCompSetup
        where priceMarginCompSetup.PriceComponentCodeName == _priceComponentCodeName;

    return priceMarginCompSetup;
}

public display Description priceComponentCodeDescription()
{
    return this.priceComponentCode().Description;
}

public display GUPPriceComponent PriComponent()
{
    return this.priceComponentCode().PriceComponent;
}

public display RetailDiscountConcurrency ProCompConcurrency()
{
    RetailDiscountConcurrency concurrency;
    GUPPriceComponentCode priceComponentCode = this.priceComponentCode();

    switch (priceComponentCode.PriceComponent)
    {
        case GUPPriceComponent::PriceMarginComponentAdjustment:
        case GUPPriceComponent::RetailDiscounts:
            concurrency = priceComponentCode.ConcurrencyMode;

        default:
    }

    return concurrency;
}

public void modifiedField(FieldId _fieldId)
{
    super(_fieldId);

    switch (_fieldId)
    {
        case fieldNum(GUPPriceComponentCodeSetup, PostInLedger):
            if (this.PostInLedger == NoYes::Yes)
            {
                this.dataSource().object(fieldNum(GUPPriceComponentCodeSetup, LedgerDimension)).mandatory(true);
                this.dataSource().object(fieldNum(GUPPriceComponentCodeSetup, LedgerDimension)).allowEdit(true);
            }
            else
            {
                this.dataSource().object(fieldNum(GUPPriceComponentCodeSetup, LedgerDimension)).mandatory(false);
                this.dataSource().object(fieldNum(GUPPriceComponentCodeSetup, LedgerDimension)).allowEdit(false);
                this.LedgerDimension = 0;
            }
            break;
        case fieldNum(GUPPriceComponentCodeSetup, Flexible):
            if (this.Flexible == NoYes::Yes)
            {
                this.CalculationSequence = 0;
                this.dataSource().object(fieldNum(GUPPriceComponentCodeSetup, CalculationSequence)).mandatory(false);
                this.dataSource().object(fieldNum(GUPPriceComponentCodeSetup, CalculationSequence)).allowEdit(false);

                this.CompoundcalculationBasis = NoYes::No;
                this.dataSource().object(fieldNum(GUPPriceComponentCodeSetup, CompoundcalculationBasis)).allowEdit(false);
            }
            else
            {
                this.dataSource().object(fieldNum(GUPPriceComponentCodeSetup, CalculationSequence)).mandatory(true);
                this.dataSource().object(fieldNum(GUPPriceComponentCodeSetup, CalculationSequence)).allowEdit(true);

                this.dataSource().object(fieldNum(GUPPriceComponentCodeSetup, CompoundcalculationBasis)).allowEdit(true);
            }
            break;
        case fieldNum(GUPPriceComponentCodeSetup, CalculationSequence):
            this.validateCalculationSequence();
            break;
    }
}

public void initValue()
{

    super();

    FormObjectSet formObjectSet = this.dataSource();

    if  (formObjectSet != null)
    {
        this.PostInLedger = NoYes::No;
        this.dataSource().object(fieldNum(GUPPriceComponentCodeSetup, LedgerDimension)).mandatory(false);
        this.dataSource().object(fieldNum(GUPPriceComponentCodeSetup, LedgerDimension)).allowEdit(false);

        this.Flexible = NoYes::No;
        this.dataSource().object(fieldNum(GUPPriceComponentCodeSetup, CalculationSequence)).mandatory(true);
        this.dataSource().object(fieldNum(GUPPriceComponentCodeSetup, CalculationSequence)).allowEdit(true);
        this.dataSource().object(fieldNum(GUPPriceComponentCodeSetup, CompoundcalculationBasis)).allowEdit(true);
    }
}

public static boolean existCalcSequence(GUPCalculationSequenceNum _calcSequence)
{
    return (select firstonly CalculationSequence from GUPPriceComponentCodeSetup
               where GUPPriceComponentCodeSetup.CalculationSequence == _calcSequence).CalculationSequence;
}

public boolean validateCalculationSequence()
{
    GUPPriceComponentCodeSetup priceMarginComponentSetup;
    boolean isEqual;
    boolean ret = true;

    if (this.Flexible == NoYes::No)
    {
        select firstonly RecId from priceMarginComponentSetup
            where priceMarginComponentSetup.CalculationSequence == this.CalculationSequence
                && priceMarginComponentSetup.RecId != this.RecId;

        if (priceMarginComponentSetup.RecId)
        {
            ret = checkFailed(strFmt("@GlobalUnifiedPricing:GUPCalculationCompoundError", this.CalculationSequence));
        }
    }

    return ret;
}

public boolean validateWrite()
{
    boolean ret;

    ret = super();

    if (ret)
    {
        if (this.PostInLedger == NoYes::No && this.LedgerDimension)
        {
            ret = checkFailed(strFmt("@GlobalUnifiedPricing:GUPLedgerDimensionValidation", this.LedgerDimension, this.PostInLedger));
        }

        if (this.Flexible == NoYes::Yes)
        {
            if (this.CalculationSequence)
            {
                ret = checkFailed(strFmt("@GlobalUnifiedPricing:GUPCalculationSequenceValidation'", this.Flexible));
            }

            if (this.CompoundcalculationBasis)
            {
                ret = checkFailed(strFmt("@GlobalUnifiedPricing:GUPCompoundCalculationBasisValidation", this.Flexible));
            }
        }
        else
        {
            ret = this.validateCalculationSequence();
        }
    }

    return ret;
}
